// reproduce.js
// This minimal script spawns the Lighthouse CLI exactly as in the screenshot
// and demonstrates that on a fatal error you see the ICU template key

const {spawnSync} = require('child_process');
const path = require('path');

(async function main() {
  // Adjust this to point at your local checkout of the lighthouse CLI entry point
  const cliScript = path.join(__dirname, 'lighthouse-cli', 'run.js');
  // Try with a URL that will trigger an INVALID_URL error path
  const args = [cliScript, 'not-a-valid-url', '--view'];

  // Spawn `node run.js not-a-valid-url --view`
  const result = spawnSync(process.execPath, args, {encoding: 'utf-8'});

  console.log('=== stdout ===');
  console.log(result.stdout.trim());
  console.log('=== stderr ===');
  console.log(result.stderr.trim());
})();
